BEGIN;

-- Migration 006: empower.empowered_profiles
--
-- Core tier-3 table. An empowered_profiles row existing = user is an Empowered member.
-- Tier is determined by child record presence, NEVER a status flag.
--
-- legal_name: public-facing name of the civic leader (readable on active profiles by anyone).
--   For INACTIVE profiles, the entire row is hidden from non-owners (see migration 009).
--
-- candidate_page_slug: unique identifier for public candidate pages (Phase 8).
--   Generated by execute_empowerment RPC: kebab-case(legal_name) + 4-char random suffix.
--   Slug is permanent — preserved even after demotion (is_active = false).
--   Slug is never reassigned to another user (CAND-03).
--
-- is_active: false after demotion. Only the RPC function sets this; never set directly by app code.
--   Setting is_active = false is the sole demotion mechanism; record is never deleted.
--
-- deleted_at: soft delete support; NULL = active.

CREATE TABLE IF NOT EXISTS empower.empowered_profiles (
  id                   UUID    PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id              UUID    NOT NULL UNIQUE REFERENCES public.users(id) ON DELETE CASCADE,
  connected_profile_id UUID    NOT NULL REFERENCES connect.connected_profiles(id),
  legal_name           TEXT    NOT NULL,
  empowered_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  is_active            BOOLEAN NOT NULL DEFAULT true,
  candidate_page_slug  TEXT    UNIQUE,   -- permanent; never reassigned
  deleted_at           TIMESTAMPTZ,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Primary lookup index
CREATE INDEX IF NOT EXISTS idx_empowered_profiles_user_id
  ON empower.empowered_profiles(user_id);

-- Partial index: slug lookups for Phase 8 public candidate pages.
-- Only rows WITH a slug are indexed — keeps the index tight.
CREATE INDEX IF NOT EXISTS idx_empowered_profiles_slug
  ON empower.empowered_profiles(candidate_page_slug)
  WHERE candidate_page_slug IS NOT NULL;

-- Partial index: active empowered users only (most queries target active).
CREATE INDEX IF NOT EXISTS idx_empowered_profiles_active
  ON empower.empowered_profiles(user_id)
  WHERE is_active = true;

COMMIT;
